\noindent With this notation, the \avgm\ algorithm is very simple to
describe:
%
\paragraph{Average mixture algorithm}
\begin{enumerate}
\item[(1)] For each $i \in \{1, \ldots, \nummac\}$, processor $i$ uses
  its local dataset $\samples_{1, i}$ to compute the local empirical
  minimizer
  \begin{align}
    \label{EqnDefnLocalEmpMin}
    \optvar_{1, i} & \in \argmin_{\optvar \in \optvarspace}
    \MYMIN{\underbrace{\frac{1}{|S_{1,i}|} \sum_{x \in S_{1,i}} f(\optvar;
      x)}_{F_{1,i}(\optvar)}}.
  \end{align}
\item[(2)] These $\nummac$ local estimates are then averaged
  together---that is, we compute
  \begin{equation}
    \label{eqn:avgm-alg-def}
   \optavg_1 = \frac{1}{\nummac} \sum_{i = 1}^\nummac \optvar_{1, i}.
  \end{equation}
\end{enumerate}

